$schema = new \GnuCms\Extension\PackageSchema(
    $context->app->db(), $context->app->storageDir()
);
$context->route('POST', '/install',
    static function ($request, $response) use ($schema) {
        $schema->install('modules/hello', 1, ['hello_records'],
            static function ($db, int $previousVersion): void {
                $db->execute('CREATE TABLE IF NOT EXISTS '
                    . $db->table('hello_records')
                    . ' (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,'
                    . ' title VARCHAR(100) NOT NULL)'
                    . ' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
            });
        return $response->withStatus(303)
            ->withHeader('Location', $request->getUri()->getPath());
    }, admin: true);
